function mostSortedPieces(arr: number[]): number {
  let pieces = 0;
  for (let i = 0; i < arr.length; i++) {
    const pre = arr.slice(0, i + 1).sort((a, b) => a - b);
    if (pre.every((v, k) => v === k)) pieces++;
  }
  return pieces;
}

