function mostSortedPieces(arr: number[]): number {
  let mx = -1, pieces = 0;
  for (let i = 0; i < arr.length; i++) {
    mx = Math.max(mx, arr[i]);
    if (mx === i) pieces++;
  }
  return pieces;
}

